CREATE TABLE IF NOT EXISTS economic_calibration_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recalibration_id uuid NOT NULL, profile_id uuid NOT NULL, status text NOT NULL DEFAULT 'pending', requested_by text NOT NULL, reviewer_id text, review_notes text, proposed_change jsonb NOT NULL DEFAULT '{}'::jsonb, approved_for_production boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz);
CREATE TABLE IF NOT EXISTS economic_calibration_governance_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), review_id uuid NOT NULL, recalibration_id uuid NOT NULL, profile_id uuid NOT NULL, event_type text NOT NULL, actor_id text NOT NULL, from_status text, to_status text NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_calibration_reviews_profile ON economic_calibration_reviews(profile_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_calibration_events_review ON economic_calibration_governance_events(review_id,created_at DESC);